<?php $ov=static fn($key,$default='')=>e((string)($values[$key]??$default)); ?>
<fieldset><legend>Organisation & role</legend><div class="opp-fields">
<?php foreach(['organisation'=>'Organisation name','title'=>'Role title']as$key=>$label):?><label><?=$label?><input name="<?=$key?>" maxlength="180" required value="<?=$ov($key)?>"></label><?php endforeach;?>
<label>Opportunity type<select name="type"><?php foreach(opportunity_types()as$key=>$label):?><option value="<?=$key?>" <?=($values['type']??'FULL_TIME')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<label>Employment duration<select name="permanence"><?php foreach(['permanent'=>'Permanent','temporary'=>'Temporary / fixed term','not_applicable'=>'Not applicable']as$key=>$label):?><option value="<?=$key?>" <?=($values['permanence']??'permanent')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label>
<label>Number of positions<input type="number" name="positions" min="1" max="10000" value="<?=$ov('positions',1)?>" required></label>
<label>Workplace<select name="mode"><?php foreach(['on_site'=>'On site','hybrid'=>'Hybrid','remote'=>'Remote']as$key=>$label):?><option value="<?=$key?>" <?=($values['mode']??'on_site')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></div>
<label>Eligible countries for remote work<input name="remote_countries" maxlength="1000" value="<?=$ov('remote_countries')?>" placeholder="Kenya, Uganda, Tanzania"><small>Required for remote roles. Separate country names with commas.</small></label>
</fieldset>
<?php $locationValues=$values;$locationPrefix='opportunity';$locationCountryLabel='Workplace country';$locationCountryRequired=true;$locationLegend='Workplace location';$locationPhone=false;include __DIR__.'/../partials_location_fields.php'; ?>
<fieldset><legend>What the opportunity involves</legend><?php foreach(['purpose'=>['Role purpose',3000],'responsibilities'=>['Responsibilities',8000],'essential'=>['Essential criteria',5000],'desirable'=>['Desirable criteria · optional',3000],'accessibility'=>['Accessibility & adjustments · optional',2000]]as$key=>[$label,$max]):?><label><?=e($label)?><textarea name="<?=$key?>" rows="4" maxlength="<?=$max?>" <?=in_array($key,['purpose','responsibilities','essential'],true)?'required':''?>><?=$ov($key)?></textarea></label><?php endforeach;?></fieldset>
<fieldset><legend>Compensation</legend><div class="opp-fields"><label>Payment<select name="paid"><option value="paid" <?=($values['paid']??'paid')==='paid'?'selected':''?>>Paid</option><option value="unpaid" <?=($values['paid']??'')==='unpaid'?'selected':''?>>Unpaid · internships / volunteering only</option></select></label><label>Currency<input name="currency" maxlength="3" value="<?=$ov('currency','KES')?>" required></label>
<label>Minimum amount<input name="salary_min" inputmode="decimal" value="<?=$ov('salary_min')?>"></label><label>Maximum amount<input name="salary_max" inputmode="decimal" value="<?=$ov('salary_max')?>"></label>
<label>Per<select name="salary_period"><?php foreach(['HOUR'=>'Hour','DAY'=>'Day','WEEK'=>'Week','MONTH'=>'Month','YEAR'=>'Year']as$key=>$label):?><option value="<?=$key?>" <?=($values['salary_period']??'MONTH')===$key?'selected':''?>><?=$label?></option><?php endforeach;?></select></label></div>
<label>If compensation is not disclosed, explain why<textarea name="compensation_reason" maxlength="500" rows="2"><?=$ov('compensation_reason')?></textarea></label></fieldset>
<fieldset><legend>Applications & deadline</legend><label>Application destination<input name="apply_url" maxlength="1000" value="<?=$ov('apply_url')?>" placeholder="https://… or mailto:jobs@example.org" required></label><small>Public employer application page or email. Do not enter private access tokens. Applicants must not pay a fee.</small>
<label>How to apply<textarea name="application_process" maxlength="3000" rows="3" required><?=$ov('application_process')?></textarea></label><div class="opp-fields"><label>Closing date & time<input type="datetime-local" name="closing_local" value="<?=$ov('closing_local')?>" required></label><label>Timezone<input name="timezone" list="opportunity-timezones" value="<?=$ov('timezone','Africa/Nairobi')?>" required></label></div><datalist id="opportunity-timezones"><?php foreach(DateTimeZone::listIdentifiers()as$tz):?><option value="<?=e($tz)?>"><?php endforeach;?></datalist></fieldset>
